{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "example-live-artifact",
  "title": "Live Artifact",
  "title_i18n": {
    "zh-CN": "实时工件",
    "zh-TW": "即時工件",
    "ja": "ライブアーティファクト",
    "ko": "라이브 아티팩트",
    "de": "Live-Artefakt",
    "fr": "Artefact en direct",
    "ru": "Живой артефакт",
    "es": "Artefacto en vivo",
    "pt-BR": "Artefato ao vivo",
    "it": "Artefatto live",
    "vi": "Tạo phẩm trực tiếp",
    "pl": "Artefakt na żywo",
    "id": "Artefak Langsung",
    "nl": "Live artefact",
    "ar": "القطعة الحية",
    "tr": "Canlı Yapı Taşı",
    "uk": "Живий артефакт",
    "en": "Live Artifact"
  },
  "version": "0.1.0",
  "description": "Create refreshable, auditable Open Design artifacts backed by connector or local data. Trigger when the user asks for live dashboards, refreshable reports, synced views, or reusable data-backed artifacts.",
  "description_i18n": {
    "zh-CN": "创建可刷新、可审计的 Open Design 工件，支持连接器或本地数据。适用于实时仪表板、可刷新报表、同步视图或可复用的数据驱动工件。",
    "zh-TW": "建立可重新整理、可稽核的 Open Design 工件，支援連接器或本機資料。適用於即時儀表板、可重新整理報表、同步檢視或可重複使用的資料驅動工件。",
    "ja": "コネクタまたはローカルデータに基づく、更新可能で監査可能な Open Design アーティファクトを作成。ライブダッシュボード、更新可能なレポート、同期ビュー、再利用可能なデータ駆動アーティファクトに対応。",
    "ko": "커넥터 또는 로컬 데이터를 기반으로 새로고침 및 감사 가능한 Open Design 아티팩트를 생성합니다. 라이브 대시보드, 새로고침 가능한 보고서, 동기화된 뷰 또는 재사용 가능한 데이터 기반 아티팩트에 적합합니다.",
    "de": "Erstellen Sie aktualisierbare und überprüfbare Open Design-Artefakte, die auf Connector- oder lokalen Daten basieren. Ideal für Live-Dashboards, aktualisierbare Berichte, synchronisierte Ansichten oder wiederverwendbare datengestützte Artefakte.",
    "fr": "Créez des artefacts Open Design actualisables et auditables basés sur des connecteurs ou des données locales. Idéal pour les tableaux de bord en direct, les rapports actualisables, les vues synchronisées ou les artefacts réutilisables basés sur les données.",
    "ru": "Создавайте обновляемые и аудируемые артефакты Open Design на основе коннекторов или локальных данных. Подходит для живых дашбордов, обновляемых отчетов, синхронизированных представлений или переиспользуемых артефактов на основе данных.",
    "es": "Crea artefactos de Open Design actualizables y auditables respaldados por conectores o datos locales. Ideal para dashboards en vivo, informes actualizables, vistas sincronizadas o artefactos reutilizables basados en datos.",
    "pt-BR": "Crie artefatos Open Design atualizáveis e auditáveis suportados por conectores ou dados locais. Ideal para dashboards ao vivo, relatórios atualizáveis, visualizações sincronizadas ou artefatos reutilizáveis baseados em dados.",
    "it": "Crea artefatti Open Design aggiornabili e verificabili supportati da connettori o dati locali. Ideale per dashboard live, report aggiornabili, viste sincronizzate o artefatti riutilizzabili basati su dati.",
    "vi": "Tạo các tạo phẩm Open Design có thể làm mới và kiểm toán, được hỗ trợ bởi connector hoặc dữ liệu cục bộ. Kích hoạt cho dashboard trực tiếp, báo cáo có thể làm mới, chế độ xem đồng bộ hoặc tạo phẩm dựa trên dữ liệu có thể tái sử dụng.",
    "pl": "Twórz odświeżalne i audytowalne artefakty Open Design oparte na konektorach lub danych lokalnych. Idealne do dashboardów na żywo, odświeżalnych raportów, synchronizowanych widoków lub wielokrotnego użytku artefaktów opartych na danych.",
    "id": "Buat artefak Open Design yang dapat disegarkan dan diaudit, didukung oleh konektor atau data lokal. Cocok untuk dasbor langsung, laporan yang dapat disegarkan, tampilan tersinkronisasi, atau artefak berbasis data yang dapat digunakan kembali.",
    "nl": "Creëer vernieuwbare en controleerbare Open Design-artefacten ondersteund door connector- of lokale gegevens. Geschikt voor live dashboards, vernieuwbare rapporten, gesynchroniseerde weergaven of herbruikbare datagestuurd artefacten.",
    "ar": "أنشئ قطع Open Design قابلة للتحديث والمراجعة مدعومة بموصل أو بيانات محلية. مناسبة للوحات المعلومات الحية والتقارير القابلة للتحديث والطرق المتزامنة أو القطع القابلة لإعادة الاستخدام المستندة إلى البيانات.",
    "tr": "Bağlayıcı veya yerel verilerle desteklenen yenilenebilir ve denetlenebilir Open Design yapı taşları oluşturun. Canlı panolar, yenilenebilir raporlar, senkronize görünümler veya yeniden kullanılabilir veri destekli yapı taşları için idealdir.",
    "uk": "Створюйте оновлювані та аудитовані артефакти Open Design на основі коннекторів або локальних даних. Підходить для живих дашбордів, оновлюваних звітів, синхронізованих представлень або багаторазових артефактів на основі даних.",
    "en": "Create refreshable, auditable Open Design artifacts backed by connector or local data. Trigger when the user asks for live dashboards, refreshable reports, synced views, or reusable data-backed artifacts."
  },
  "license": "MIT",
  "author": {
    "name": "Open Design",
    "url": "https://github.com/nexu-io"
  },
  "homepage": "https://github.com/nexu-io/open-design/tree/main/plugins/_official/examples/live-artifact",
  "tags": [
    "example",
    "first-party",
    "prototype",
    "live",
    "web",
    "live-artifact",
    "live-dashboard",
    "refreshable-dashboard",
    "live-report",
    "refreshable-report",
    "synced-view",
    "untitled"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "prototype",
    "scenario": "live",
    "surface": "web",
    "preview": {
      "type": "html",
      "entry": "./index.html"
    },
    "useCase": {
      "query": {
        "en": "Create refreshable, auditable Open Design artifacts backed by connector or local data. Trigger when the user asks for live dashboards, refreshable reports, synced views, or reusable data-backed artifacts.",
        "zh-CN": "使用这个插件完成以下任务：Create refreshable, auditable Open Design artifacts backed by connector or local data. Trigger when the user asks for live dashboards, refreshable reports, synced views, or reusable data-backed artifacts."
      }
    },
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "designSystem": {
        "primary": true
      },
      "assets": [
        "./references/artifact-schema.md",
        "./references/connector-policy.md",
        "./references/refresh-contract.md"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "generate",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write"
    ]
  }
}
